#!/usr/bin/env python3
"""PreToolUse hook: deny Edit/Write on jzero/goctl generated files.

Detection rules:
1. File header (first 10 lines) contains a generated "DO NOT EDIT" marker
   ("Code generated by jzero. DO NOT EDIT." / "Code generated by goctl.
   Templates Edited by jzero. DO NOT EDIT.").
2. Path matches this repo's generated compact-handler convention
   (internal/handler/**/*_compact.go — generated without a header comment).

Exit codes: 0 pass, 2 block (deny for PreToolUse).
"""
import json
import os
import re
import sys

COMPACT_RE = re.compile(r"/internal/handler/.+_compact\.go$")

BLOCK_MSG = (
    "拒绝修改生成文件: {path}\n"
    "该文件是 jzero/goctl 的生成物（Code generated ... DO NOT EDIT），"
    "手改内容会在下次 `jzero gen` 时被覆盖。\n"
    "正确做法：\n"
    "1. 改路由/类型/模型 → 修改 server/desc/ 下的 .api / .sql 定义，然后运行 `jzero gen` 重新生成；\n"
    "2. 加业务逻辑 → 写在伴生的手写文件里（如 *_model.go、internal/logic/...）；\n"
    "3. 合并冲突涉及生成文件 → 保留两侧改动后用 `jzero gen` 重新生成收敛，不要手写合并结果。\n"
    "如确属 codegen 缺陷需要临时绕过，请先向用户说明并取得确认。"
)


def main() -> int:
    try:
        data = json.load(sys.stdin)
    except Exception:
        return 0
    path = (data.get("tool_input") or {}).get("file_path") or ""
    if not path:
        return 0
    norm = os.path.abspath(path).replace(os.sep, "/")
    if COMPACT_RE.search(norm):
        print(BLOCK_MSG.format(path=path), file=sys.stderr)
        return 2
    try:
        with open(norm, encoding="utf-8", errors="ignore") as fh:
            head = "".join(fh.readline() for _ in range(10))
    except OSError:
        return 0
    low = head.lower()
    if "do not edit" in low and "generated" in low:
        print(BLOCK_MSG.format(path=path), file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())
